{
  "findings": [
    {
      "check_id": "CKV_AZURE_59",
      "title": "Storage account permits public network access",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Public network access is not disabled, leaving the storage account endpoints reachable from public networks."
    },
    {
      "check_id": "CKV_AZURE_33",
      "title": "Queue service logging is not enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The account has no Queue Storage Analytics logging for read, write, or delete operations, reducing visibility into data access and modification."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Obsolete minimum TLS version",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The account explicitly permits TLS 1.0, which is obsolete and vulnerable to known protocol weaknesses."
    },
    {
      "check_id": "CKV_AZURE_3",
      "title": "HTTPS-only traffic is disabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The account explicitly allows non-HTTPS traffic, which can expose storage data and credentials in transit."
    },
    {
      "check_id": "CKV_AZURE_190",
      "title": "Blob public access is not restricted",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The account does not explicitly prevent nested blob resources from being configured for public access."
    },
    {
      "check_id": "CKV2_AZURE_40",
      "title": "Shared Key authorization is enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Shared Key authorization is enabled by default, allowing long-lived account keys to bypass identity-based Azure AD authorization."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Anonymous blob access is not disabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The account does not explicitly disable anonymous access for nested blob containers and objects."
    },
    {
      "check_id": "CKV2_AZURE_41",
      "title": "SAS expiration policy is missing",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "No SAS expiration policy is configured, so generated SAS tokens are not governed by an account-level expiration interval."
    },
    {
      "check_id": "CKV2_AZURE_38",
      "title": "Blob and container soft delete are disabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Versioning is enabled, but deleted blobs and containers have no retention policy, limiting recovery from accidental or malicious deletion."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                              = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name               = azurerm_resource_group.corporate_media_streaming.name\n  location                          = azurerm_resource_group.corporate_media_streaming.location\n  account_tier                      = \"Standard\"\n  account_replication_type          = \"GRS\"\n  enable_https_traffic_only         = true\n  min_tls_version                   = \"TLS1_2\"\n  public_network_access_enabled     = false\n  allow_nested_items_to_be_public   = false\n  shared_access_key_enabled         = false\n\n  sas_policy {\n    expiration_period = \"01.00:00:00\"\n    expiration_action = \"Log\"\n  }\n\n  blob_properties {\n    versioning_enabled = true\n\n    delete_retention_policy {\n      days = 7\n    }\n\n    container_delete_retention_policy {\n      days = 7\n    }\n  }\n\n  queue_properties {\n    logging {\n      delete                = true\n      read                  = true\n      write                 = true\n      version               = \"1.0\"\n      retention_policy_days = 7\n    }\n  }\n}\n",
  "fix_summary": "Enabled HTTPS-only traffic and TLS 1.2, disabled public network, anonymous blob, and Shared Key access, and added a SAS expiration policy. Also enabled Queue logging and seven-day soft-delete retention for blobs and containers."
}
